import Fastify, { type FastifyInstance, type FastifyReply, type FastifyRequest } from "fastify";
import cors from "@fastify/cors";
import type { AppConfig, RateLimitConfig } from "./config.js";
import { Store, type AccountRow } from "./database.js";
import { ApiError, validationError, type ValidationIssue } from "./errors.js";
import { prepareDummyHash } from "./crypto/password.js";
import { CHAIN_ID, NETWORK } from "./crypto/wallet.js";
import { SlidingWindowRateLimiter } from "./rate-limit.js";
import { AuthService, normalizeEmail, publicAccount } from "./services/auth-service.js";
import { WalletService } from "./services/wallet-service.js";

declare module "fastify" {
  interface FastifyRequest {
    authenticatedAccount?: AccountRow;
    loginAuditOutcome?: {
      result: "SUCCESS" | "FAILURE";
      reason?: string;
    };
    pendingPublicRateLimit?: {
      kind: "register" | "login";
      retryAfterSeconds: number;
    };
  }

  interface FastifyInstance {
    exchangeStore: Store;
    authService: AuthService;
    walletService: WalletService;
  }
}

const EMAIL_PATTERN = /^[^@\s]+@[^@\s.]+(\.[^@\s.]+)+$/;
const KNOWN_ROUTES: Readonly<Record<string, readonly string[]>> = {
  "/api/v1/auth/register": ["POST"],
  "/api/v1/auth/login": ["POST"],
  "/api/v1/me": ["GET"],
  "/api/v1/deposit-address": ["GET"],
  "/health": ["GET"],
};

interface CredentialsBody {
  email: string;
  password: string;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function validateCredentialsBody(value: unknown, exactFields: boolean): CredentialsBody {
  const issues: ValidationIssue[] = [];
  if (!isRecord(value)) {
    throw validationError([{ field: "body", message: "Debe ser un objeto JSON" }]);
  }
  if (!("email" in value)) issues.push({ field: "email", message: "Campo requerido" });
  else if (typeof value.email !== "string") issues.push({ field: "email", message: "Debe ser string" });
  if (!("password" in value)) issues.push({ field: "password", message: "Campo requerido" });
  else if (typeof value.password !== "string") {
    issues.push({ field: "password", message: "Debe ser string" });
  }
  if (exactFields) {
    for (const field of Object.keys(value)) {
      if (field !== "email" && field !== "password") {
        issues.push({ field, message: "Campo desconocido" });
      }
    }
  }
  if (issues.length > 0) throw validationError(issues);
  return value as unknown as CredentialsBody;
}

function validateRegistration(body: CredentialsBody): CredentialsBody {
  const email = normalizeEmail(body.email);
  if (email.length > 254 || !EMAIL_PATTERN.test(email)) {
    throw validationError([{ field: "email", message: "Formato de email inválido" }]);
  }
  const passwordLength = [...body.password].length;
  if (passwordLength < 8 || passwordLength > 128) {
    throw validationError([{ field: "password", message: "Debe tener entre 8 y 128 caracteres" }]);
  }
  return { email, password: body.password };
}

function bearerToken(request: FastifyRequest): string | undefined {
  const authorization = request.headers.authorization;
  if (typeof authorization !== "string") return undefined;
  const match = /^Bearer ([^\s]+)$/.exec(authorization);
  return match?.[1];
}

function sendRateLimit(reply: FastifyReply, retryAfterSeconds: number): never {
  reply.header("Retry-After", String(retryAfterSeconds));
  throw new ApiError("RATE_LIMITED", { retryAfterSeconds });
}

function isLoginRequest(request: FastifyRequest): boolean {
  return request.method === "POST" && request.url.split("?", 1)[0] === "/api/v1/auth/login";
}

function loginAttemptEmail(request: FastifyRequest): string {
  return isRecord(request.body) && typeof request.body.email === "string"
    ? request.body.email
    : "";
}

export async function buildApp(config: AppConfig): Promise<FastifyInstance> {
  const app = Fastify({
    logger: false,
    exposeHeadRoutes: false,
    routerOptions: { ignoreTrailingSlash: false },
  });
  const store = new Store(config);
  const walletService = new WalletService(store);
  const authService = new AuthService(store, walletService);
  const publicLimiter = new SlidingWindowRateLimiter();
  const protectedLimiter = new SlidingWindowRateLimiter();
  await prepareDummyHash();

  await app.register(cors, {
    origin: config.webOrigins ?? ["http://localhost:5173", "http://127.0.0.1:5173"],
    methods: ["GET", "POST", "DELETE", "OPTIONS"],
    allowedHeaders: ["Content-Type", "Authorization"],
    credentials: false,
  });

  app.decorate("exchangeStore", store);
  app.decorate("walletService", walletService);
  app.decorate("authService", authService);

  app.addHook("onClose", async () => {
    store.close();
  });

  app.setErrorHandler((error, request, reply) => {
    if (request.pendingPublicRateLimit) {
      const retryAfterSeconds = request.pendingPublicRateLimit.retryAfterSeconds;
      const apiError = new ApiError("RATE_LIMITED", { retryAfterSeconds });
      if (isLoginRequest(request)) {
        request.loginAuditOutcome = { result: "FAILURE", reason: apiError.code };
      }
      reply.header("Retry-After", String(retryAfterSeconds));
      reply.status(apiError.status).send(apiError.toBody());
      return;
    }
    if (error instanceof ApiError) {
      if (isLoginRequest(request)) {
        request.loginAuditOutcome = { result: "FAILURE", reason: error.code };
      }
      reply.status(error.status).send(error.toBody());
      return;
    }
    const fastifyError = error as Error & { code?: string; statusCode?: number };
    if (
      fastifyError.code === "FST_ERR_CTP_INVALID_MEDIA_TYPE" ||
      fastifyError.code === "FST_ERR_CTP_EMPTY_JSON_BODY" ||
      fastifyError.code === "FST_ERR_CTP_BODY_TOO_LARGE" ||
      fastifyError.statusCode === 400
    ) {
      const apiError = validationError([{ field: "body", message: "JSON inválido o Content-Type no soportado" }]);
      if (isLoginRequest(request)) {
        request.loginAuditOutcome = { result: "FAILURE", reason: apiError.code };
      }
      reply.status(apiError.status).send(apiError.toBody());
      return;
    }
    const apiError = new ApiError("INTERNAL_ERROR");
    if (isLoginRequest(request)) {
      request.loginAuditOutcome = { result: "FAILURE", reason: apiError.code };
    }
    reply.status(apiError.status).send(apiError.toBody());
  });

  app.addHook("onResponse", async (request) => {
    if (!isLoginRequest(request)) return;
    const outcome = request.loginAuditOutcome ?? { result: "FAILURE", reason: "INTERNAL_ERROR" } as const;
    authService.auditLoginAttempt(
      loginAttemptEmail(request),
      outcome.result,
      outcome.reason,
      request.ip,
    );
  });

  app.setNotFoundHandler((request, reply) => {
    const path = request.url.split("?", 1)[0] ?? request.url;
    const allowed = KNOWN_ROUTES[path];
    const error = allowed && !allowed.includes(request.method)
      ? new ApiError("METHOD_NOT_ALLOWED", { method: request.method, allowed })
      : new ApiError("NOT_FOUND", { resource: "route", id: path });
    reply.status(error.status).send(error.toBody());
  });

  app.get("/health", async () => ({ status: "ok" }));

  const publicRateLimitCheck = (kind: "register" | "login", rateConfig: RateLimitConfig | undefined) =>
    async (request: FastifyRequest): Promise<void> => {
      if (!rateConfig) return;
      const result = publicLimiter.check(`${kind}:${request.ip}`, rateConfig);
      if (result.limited) {
        request.pendingPublicRateLimit = { kind, retryAfterSeconds: result.retryAfterSeconds };
      }
    };

  const enforcePublicRateLimit = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const pending = request.pendingPublicRateLimit;
    if (!pending) return;
    sendRateLimit(reply, pending.retryAfterSeconds);
  };

  app.post(
    "/api/v1/auth/register",
    {
      onRequest: publicRateLimitCheck("register", config.registerRateLimit),
      preValidation: enforcePublicRateLimit,
    },
    async (request, reply) => {
      const schemaValid = validateCredentialsBody(request.body, true);
      const body = validateRegistration(schemaValid);
      if (store.findAccountByEmail(body.email)) {
        throw new ApiError("EMAIL_ALREADY_EXISTS", { email: body.email });
      }
      const account = await authService.register(body.email, body.password);
      reply.status(201).send(account);
    },
  );

  app.post(
    "/api/v1/auth/login",
    {
      onRequest: publicRateLimitCheck("login", config.loginRateLimit),
      preValidation: enforcePublicRateLimit,
    },
    async (request, reply) => {
      const body = validateCredentialsBody(request.body, false);
      const result = await authService.login(body.email, body.password);
      request.loginAuditOutcome = { result: "SUCCESS" };
      reply.status(200).send(result);
    },
  );

  const authenticate = async (request: FastifyRequest): Promise<void> => {
    const token = bearerToken(request);
    const account = token ? authService.authenticate(token) : undefined;
    if (!account) throw new ApiError("UNAUTHENTICATED");
    request.authenticatedAccount = account;
  };

  const protectedRateLimit = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const account = request.authenticatedAccount;
    if (!account) throw new ApiError("UNAUTHENTICATED");
    const result = protectedLimiter.check(
      `${account.account_id}:${request.routeOptions.url}`,
      { max: 60, windowSeconds: 60 },
    );
    if (result.limited) sendRateLimit(reply, result.retryAfterSeconds);
  };

  app.get(
    "/api/v1/me",
    { preHandler: [authenticate, protectedRateLimit] },
    async (request, reply) => {
      const account = request.authenticatedAccount;
      if (!account) throw new ApiError("UNAUTHENTICATED");
      reply.status(200).send(publicAccount(account));
    },
  );

  app.get(
    "/api/v1/deposit-address",
    { preHandler: [authenticate, protectedRateLimit] },
    async (request, reply) => {
      const query = isRecord(request.query) ? request.query : {};
      const asset = query.asset;
      if (typeof asset !== "string" || (asset !== "ETH" && asset !== "USDC")) {
        throw validationError([{ field: "asset", message: "Debe ser ETH o USDC" }]);
      }

      const chainId = query.chainId;
      const network = query.network;
      if (chainId !== undefined && String(chainId) !== CHAIN_ID) {
        throw new ApiError("CHAIN_ID_MISMATCH", { expected: CHAIN_ID, got: String(chainId) });
      }
      if (network !== undefined && String(network).toLowerCase() !== NETWORK) {
        throw new ApiError("CHAIN_ID_MISMATCH", { expected: CHAIN_ID, got: String(network) });
      }

      const account = request.authenticatedAccount;
      if (!account) throw new ApiError("UNAUTHENTICATED");
      const assigned = walletService.getOrAssign(account.account_id);
      const response: Record<string, string> = {
        asset,
        address: assigned.address,
        network: NETWORK,
        chainId: CHAIN_ID,
      };
      if (asset === "USDC") response.tokenAddress = config.usdcMockAddress;
      reply.status(200).send(response);
    },
  );

  return app;
}

import { getAddress } from "ethers";

export interface AppConfig {
  host: string;
  port: number;
  databasePath: string;
  sessionTtlSeconds: number;
  walletEncryptionKey: Buffer;
  usdcMockAddress: string;
  sepoliaRpcUrl: string;
  hdMnemonic?: string;
  hdMnemonicPassphrase: string;
  registerRateLimit?: RateLimitConfig;
  loginRateLimit?: RateLimitConfig;
  webOrigins?: string[];
}

export interface RateLimitConfig {
  max: number;
  windowSeconds: number;
}

function positiveInt(name: string, raw: string | undefined, fallback?: number): number {
  if (raw === undefined && fallback !== undefined) return fallback;
  if (raw === undefined || !/^[1-9][0-9]*$/.test(raw)) {
    throw new Error(`INTERNAL_ERROR: ${name} debe ser un entero positivo`);
  }
  const value = Number(raw);
  if (!Number.isSafeInteger(value)) {
    throw new Error(`INTERNAL_ERROR: ${name} está fuera de rango`);
  }
  return value;
}

function encryptionKey(raw: string | undefined): Buffer {
  if (!raw) throw new Error("INTERNAL_ERROR: falta WALLET_ENCRYPTION_KEY");
  const value = raw.startsWith("base64:")
    ? Buffer.from(raw.slice(7), "base64")
    : Buffer.from(raw, "hex");
  if (value.length !== 32) {
    throw new Error("INTERNAL_ERROR: WALLET_ENCRYPTION_KEY debe contener exactamente 32 bytes");
  }
  return value;
}

function optionalRateLimit(
  env: NodeJS.ProcessEnv,
  maxName: string,
  windowName: string,
): RateLimitConfig | undefined {
  const max = env[maxName];
  const window = env[windowName];
  if (max === undefined && window === undefined) return undefined;
  if (max === undefined || window === undefined) {
    throw new Error(`INTERNAL_ERROR: ${maxName} y ${windowName} deben configurarse juntos`);
  }
  return { max: positiveInt(maxName, max), windowSeconds: positiveInt(windowName, window) };
}

export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const ttl = positiveInt("SESSION_TTL_SECONDS", env.SESSION_TTL_SECONDS, 3600);
  if (ttl < 60 || ttl > 86_400) {
    throw new Error("INTERNAL_ERROR: SESSION_TTL_SECONDS debe estar entre 60 y 86400");
  }

  if (!env.USDC_MOCK_ADDRESS) {
    throw new Error("INTERNAL_ERROR: falta USDC_MOCK_ADDRESS");
  }
  let usdcMockAddress: string;
  try {
    usdcMockAddress = getAddress(env.USDC_MOCK_ADDRESS);
  } catch {
    throw new Error("INTERNAL_ERROR: USDC_MOCK_ADDRESS no es una dirección Ethereum válida");
  }

  const sepoliaRpcUrl = env.SEPOLIA_RPC_URL;
  if (!sepoliaRpcUrl) throw new Error("INTERNAL_ERROR: falta SEPOLIA_RPC_URL");
  try {
    const url = new URL(sepoliaRpcUrl);
    if (url.protocol !== "http:" && url.protocol !== "https:") throw new Error();
  } catch {
    throw new Error("INTERNAL_ERROR: SEPOLIA_RPC_URL debe ser una URL HTTP(S) válida");
  }

  const port = positiveInt("PORT", env.PORT, 3000);
  if (port > 65_535) throw new Error("INTERNAL_ERROR: PORT está fuera de rango");

  const config: AppConfig = {
    host: env.HOST ?? "127.0.0.1",
    port,
    databasePath: env.DATABASE_PATH ?? "./data/exchange.sqlite",
    sessionTtlSeconds: ttl,
    walletEncryptionKey: encryptionKey(env.WALLET_ENCRYPTION_KEY),
    usdcMockAddress,
    sepoliaRpcUrl,
    hdMnemonicPassphrase: env.HD_MNEMONIC_PASSPHRASE ?? "",
  };
  if (env.HD_MNEMONIC !== undefined) config.hdMnemonic = env.HD_MNEMONIC;
  const registerRateLimit = optionalRateLimit(
    env,
    "REGISTER_RATE_LIMIT_MAX",
    "REGISTER_RATE_LIMIT_WINDOW_SECONDS",
  );
  if (registerRateLimit) config.registerRateLimit = registerRateLimit;
  const loginRateLimit = optionalRateLimit(
    env,
    "LOGIN_RATE_LIMIT_MAX",
    "LOGIN_RATE_LIMIT_WINDOW_SECONDS",
  );
  if (loginRateLimit) config.loginRateLimit = loginRateLimit;
  if (env.WEB_ORIGINS !== undefined) {
    const webOrigins = env.WEB_ORIGINS.split(",").map((origin) => origin.trim()).filter(Boolean);
    if (webOrigins.length === 0) {
      throw new Error("INTERNAL_ERROR: WEB_ORIGINS debe contener al menos un origen");
    }
    for (const origin of webOrigins) {
      try {
        const url = new URL(origin);
        if ((url.protocol !== "http:" && url.protocol !== "https:") || url.origin !== origin) {
          throw new Error();
        }
      } catch {
        throw new Error(`INTERNAL_ERROR: WEB_ORIGINS contiene un origen inválido: ${origin}`);
      }
    }
    config.webOrigins = webOrigins;
  }
  return config;
}

import { buildApp } from "./app.js";
import { loadConfig } from "./config.js";
import { ApiError } from "./errors.js";

async function main(): Promise<void> {
  const config = loadConfig();
  const app = await buildApp(config);
  await app.listen({ host: config.host, port: config.port });
}

main().catch((error: unknown) => {
  const code = error instanceof ApiError && error.code === "VALIDATION_ERROR"
    ? "VALIDATION_ERROR"
    : "INTERNAL_ERROR";
  process.stderr.write(`${code}: el backend no pudo iniciar de forma segura\n`);
  process.exitCode = 1;
});

