function makeConfig(databasePath: string, key: Buffer): AppConfig {
  return {
    host: "127.0.0.1",
    port: 3000,
    databasePath,
    sessionTtlSeconds: 3600,
    walletEncryptionKey: key,
    usdcMockAddress: USDC_ADDRESS,
    sepoliaRpcUrl: "http://127.0.0.1:8545",
    hdMnemonicPassphrase: "",
  };
}

async function register(app: FastifyInstance): Promise<void> {
  const response = await app.inject({
    method: "POST",
    url: "/api/v1/auth/register",
    headers: { "content-type": "application/json" },
    payload: { email: "trader@example.com", password: "Sup3rSecreta" },
  });
  expect(response.statusCode).toBe(201);
}

async function login(app: FastifyInstance): Promise<string> {
  const response = await app.inject({
    method: "POST",
    url: "/api/v1/auth/login",
    headers: { "content-type": "application/json" },
    payload: { email: "trader@example.com", password: "Sup3rSecreta" },
  });
  expect(response.statusCode).toBe(200);
  return response.json().token as string;
}

function authorization(token: string): { authorization: string } {
  return { authorization: `Bearer ${token}` };
}

async function openWebSocket(url: string, headers?: Record<string, string>): Promise<WebSocket> {
  const socket = new WebSocket(url, headers ? { headers } : undefined);
  await new Promise<void>((resolve, reject) => {
    socket.once("open", resolve);
    socket.once("error", reject);
  });
  return socket;
}

function nextJson(socket: WebSocket): Promise<Record<string, unknown>> {
  return new Promise((resolve, reject) => {
    const onMessage = (data: Buffer): void => {
      cleanup();
      try {
        resolve(JSON.parse(data.toString("utf8")) as Record<string, unknown>);
      } catch (error) {
        reject(error);
      }
    };
    const onError = (error: Error): void => {
      cleanup();
      reject(error);
    };
    const cleanup = (): void => {
      socket.off("message", onMessage);
      socket.off("error", onError);
    };
    socket.on("message", onMessage);
    socket.on("error", onError);
  });
}

function closed(socket: WebSocket): Promise<{ code: number; reason: string }> {
  return new Promise((resolve) => {
    socket.once("close", (code, reason) => resolve({ code, reason: reason.toString("utf8") }));
  });
}

describe("cierre y expiración de sesión", () => {
  let directory: string;
  let databasePath: string;
  let key: Buffer;
  let config: AppConfig;
  let app: FastifyInstance;

  beforeEach(async () => {
    directory = mkdtempSync(join(tmpdir(), "exchange-session-test-"));
    databasePath = join(directory, "exchange.sqlite");
    key = randomBytes(32);
    config = makeConfig(databasePath, key);
    app = await buildApp(config);
    await register(app);
  });

  afterEach(async () => {
    await app.close();
    rmSync(directory, { recursive: true, force: true });
  });

  it("revoca únicamente el token presentado con 204 y conserva las demás sesiones", async () => {
    const tokenA = await login(app);
    const tokenB = await login(app);
    const logout = await app.inject({
      method: "POST",
      url: "/api/v1/auth/logout",
      headers: authorization(tokenA),
    });
    expect(logout.statusCode).toBe(204);
    expect(logout.body).toBe("");

    const revoked = await app.inject({ method: "GET", url: "/api/v1/me", headers: authorization(tokenA) });
    const stillActive = await app.inject({ method: "GET", url: "/api/v1/me", headers: authorization(tokenB) });
    const repeated = await app.inject({
      method: "POST",
      url: "/api/v1/auth/logout",
      headers: authorization(tokenA),
    });
    expect(revoked.statusCode).toBe(401);
    expect(revoked.json().error.code).toBe("UNAUTHENTICATED");
    expect(repeated.json()).toEqual(revoked.json());
    expect(stillActive.statusCode).toBe(200);
  });

  it("exige Bearer válido y considera logout una ruta POST existente", async () => {
    const missing = await app.inject({ method: "POST", url: "/api/v1/auth/logout" });
    const invalid = await app.inject({
      method: "POST",
      url: "/api/v1/auth/logout",
      headers: { authorization: "Bearer inexistente" },
    });
    const wrongMethod = await app.inject({ method: "GET", url: "/api/v1/auth/logout" });
    const malformedWithoutToken = await app.inject({
      method: "POST",
      url: "/api/v1/auth/logout",
      headers: { "content-type": "application/json" },
      payload: "{invalid",
    });
    expect(missing.statusCode).toBe(401);
    expect(invalid.json()).toEqual(missing.json());
    expect(malformedWithoutToken.json()).toEqual(missing.json());
    expect(wrongMethod.statusCode).toBe(405);
    expect(wrongMethod.json().error).toMatchObject({
      code: "METHOD_NOT_ALLOWED",
      details: { method: "GET", allowed: ["POST"] },
    });
  });

  it("serializa el doble logout concurrente: exactamente uno revoca", async () => {
    const token = await login(app);
    const responses = await Promise.all([
      app.inject({ method: "POST", url: "/api/v1/auth/logout", headers: authorization(token) }),
      app.inject({ method: "POST", url: "/api/v1/auth/logout", headers: authorization(token) }),
    ]);
    expect(responses.map(({ statusCode }) => statusCode).sort()).toEqual([204, 401]);
    const later = await app.inject({ method: "GET", url: "/api/v1/me", headers: authorization(token) });
    expect(later.statusCode).toBe(401);
  });

  it("mantiene la revocación durable después de reiniciar", async () => {
    const token = await login(app);
    const logout = await app.inject({
      method: "POST",
      url: "/api/v1/auth/logout",
      headers: authorization(token),
    });
    expect(logout.statusCode).toBe(204);
    await app.close();
    app = await buildApp(makeConfig(databasePath, key));
    const response = await app.inject({ method: "GET", url: "/api/v1/me", headers: authorization(token) });
    expect(response.statusCode).toBe(401);
    expect(response.json().error.code).toBe("UNAUTHENTICATED");
  });
});

describe("WebSocket privado", () => {
  let directory: string;
  let config: AppConfig;
  let app: FastifyInstance;
  let baseUrl: string;

  const start = async (timings?: PrivateWebSocketTimings): Promise<void> => {
    app = await buildApp(config, timings);
    await app.listen({ host: "127.0.0.1", port: 0 });
    const address = app.server.address() as AddressInfo;
    baseUrl = `ws://127.0.0.1:${address.port}/api/v1/ws`;
  };

  beforeEach(async () => {
    directory = mkdtempSync(join(tmpdir(), "exchange-websocket-test-"));
    config = makeConfig(join(directory, "exchange.sqlite"), randomBytes(32));
    await start();
    await register(app);
  });

  afterEach(async () => {
    await app.close();
    rmSync(directory, { recursive: true, force: true });
  });

  it("autentica solo mediante el primer mensaje y gestiona los canales privados", async () => {
    const token = await login(app);
    const socket = await openWebSocket(baseUrl);

    let message = nextJson(socket);
    socket.send(JSON.stringify({ type: "auth", token }));
    expect(await message).toEqual({ type: "authenticated" });

    for (const channel of ["orders", "balances", "withdrawals"]) {
      message = nextJson(socket);
      socket.send(JSON.stringify({ type: "subscribe", channel }));
      expect(await message).toEqual({ type: "subscribed", channel });
    }
    message = nextJson(socket);
    socket.send(JSON.stringify({ type: "unsubscribe", channel: "orders" }));
    expect(await message).toEqual({ type: "unsubscribed", channel: "orders" });

    message = nextJson(socket);
    socket.send("no-json");
    expect(await message).toMatchObject({ error: { code: "VALIDATION_ERROR" } });
    socket.close();
  });

  it("rechaza token inválido o subscribe previo con envelope y cierre 4001", async () => {
    for (const firstMessage of [
      { type: "auth", token: "inexistente" },
      { type: "subscribe", channel: "orders" },
    ]) {
      const socket = await openWebSocket(baseUrl);
      const message = nextJson(socket);
      const close = closed(socket);
      socket.send(JSON.stringify(firstMessage));
      expect(await message).toEqual({
        error: { code: "UNAUTHENTICATED", message: expect.any(String) },
      });
      expect(await close).toMatchObject({ code: 4001 });
    }

    const expiredToken = await login(app);
    app.exchangeStore.db.prepare("UPDATE sessions SET expires_at = ?").run(new Date(0).toISOString());
    const expired = await openWebSocket(baseUrl);
    const expiredMessage = nextJson(expired);
    const expiredClose = closed(expired);
    expired.send(JSON.stringify({ type: "auth", token: expiredToken }));
    expect(await expiredMessage).toMatchObject({ error: { code: "UNAUTHENTICATED" } });
    expect(await expiredClose).toMatchObject({ code: 4001 });
  });

  it("ignora credenciales en query/header y exige auth dentro de diez segundos", async () => {
    const token = await login(app);
    await app.close();
    await start({ authTimeoutMs: 80, pingIntervalMs: 1_000, pongTimeoutMs: 500 });
    const socket = await openWebSocket(`${baseUrl}?token=${encodeURIComponent(token)}`, {
      authorization: `Bearer ${token}`,
    });
    const message = nextJson(socket);
    const close = closed(socket);
    expect(await message).toMatchObject({ error: { code: "UNAUTHENTICATED" } });
    expect(await close).toMatchObject({ code: 4001 });
  });

  it("cierra activamente con 4001 cuando vence una sesión ya autenticada", async () => {
    const token = await login(app);
    app.exchangeStore.db.prepare("UPDATE sessions SET expires_at = ?").run(
      new Date(Date.now() + 150).toISOString(),
    );
    const socket = await openWebSocket(baseUrl);
    let message = nextJson(socket);
    socket.send(JSON.stringify({ type: "auth", token }));
    expect(await message).toEqual({ type: "authenticated" });

    message = nextJson(socket);
    const close = closed(socket);
    expect(await message).toMatchObject({ error: { code: "UNAUTHENTICATED" } });
    expect(await close).toMatchObject({ code: 4001 });
  });

  it("mantiene clientes que responden pong y cierra los que omiten el heartbeat", async () => {
    const token = await login(app);
    await app.close();
    await start({ authTimeoutMs: 200, pingIntervalMs: 50, pongTimeoutMs: 30 });

    const responsive = await openWebSocket(baseUrl);
    let message = nextJson(responsive);
    responsive.send(JSON.stringify({ type: "auth", token }));
    expect(await message).toEqual({ type: "authenticated" });
    for (let count = 0; count < 2; count += 1) {
      message = nextJson(responsive);
      expect(await message).toEqual({ type: "ping" });
      responsive.send(JSON.stringify({ type: "pong" }));
    }
    expect(responsive.readyState).toBe(WebSocket.OPEN);
    responsive.close();

    const silent = await openWebSocket(baseUrl);
    message = nextJson(silent);
    silent.send(JSON.stringify({ type: "auth", token }));
    expect(await message).toEqual({ type: "authenticated" });
    expect(await nextJson(silent)).toEqual({ type: "ping" });
    const close = closed(silent);
    expect(await close).toMatchObject({ code: 4000 });
  });
});

import type { Server as HttpServer, IncomingMessage } from "node:http";
import type { Duplex } from "node:stream";
import { WebSocket, WebSocketServer } from "ws";
import { ApiError, validationError } from "./errors.js";
import type { AuthService } from "./services/auth-service.js";

export interface PrivateWebSocketTimings {
  authTimeoutMs: number;
  pingIntervalMs: number;
  pongTimeoutMs: number;
}

export const DEFAULT_PRIVATE_WEBSOCKET_TIMINGS: Readonly<PrivateWebSocketTimings> = {
  authTimeoutMs: 10_000,
  pingIntervalMs: 30_000,
  pongTimeoutMs: 10_000,
};

const PRIVATE_CHANNELS = new Set(["orders", "balances", "withdrawals"]);
const MAX_TIMER_DELAY_MS = 2_147_483_647;

interface JsonRecord {
  [key: string]: unknown;
}

interface ConnectionState {
  authenticated: boolean;
  closed: boolean;
  subscriptions: Set<string>;
  authTimer?: ReturnType<typeof setTimeout>;
  expiryTimer?: ReturnType<typeof setTimeout>;
  pingTimer?: ReturnType<typeof setInterval>;
  pongTimer?: ReturnType<typeof setTimeout>;
}

function isRecord(value: unknown): value is JsonRecord {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function encode(value: unknown): string {
  return JSON.stringify(value);
}

function send(socket: WebSocket, value: unknown): void {
  if (socket.readyState === WebSocket.OPEN) socket.send(encode(value));
}

function clearConnectionTimers(state: ConnectionState): void {
  if (state.authTimer) clearTimeout(state.authTimer);
  if (state.expiryTimer) clearTimeout(state.expiryTimer);
  if (state.pingTimer) clearInterval(state.pingTimer);
  if (state.pongTimer) clearTimeout(state.pongTimer);
}

function closeWithError(
  socket: WebSocket,
  state: ConnectionState,
  error: ApiError,
  closeCode: number,
  reason: string,
): void {
  if (state.closed) return;
  state.closed = true;
  clearConnectionTimers(state);
  if (socket.readyState !== WebSocket.OPEN) {
    socket.terminate();
    return;
  }
  socket.send(encode(error.toBody()), (sendError) => {
    if (sendError) socket.terminate();
    else socket.close(closeCode, reason);
  });
}

function closeWithoutError(
  socket: WebSocket,
  state: ConnectionState,
  closeCode: number,
  reason: string,
): void {
  if (state.closed) return;
  state.closed = true;
  clearConnectionTimers(state);
  if (socket.readyState === WebSocket.OPEN) socket.close(closeCode, reason);
  else socket.terminate();
}

function parseMessage(data: Buffer, isBinary: boolean): JsonRecord | undefined {
  if (isBinary) return undefined;
  try {
    const value: unknown = JSON.parse(data.toString("utf8"));
    return isRecord(value) ? value : undefined;
  } catch {
    return undefined;
  }
}

function scheduleExpiry(
  socket: WebSocket,
  state: ConnectionState,
  expiresAt: string,
): void {
  const expire = (): void => {
    const remaining = Date.parse(expiresAt) - Date.now();
    if (remaining <= 0) {
      closeWithError(socket, state, new ApiError("UNAUTHENTICATED"), 4001, "Unauthenticated");
      return;
    }
    state.expiryTimer = setTimeout(expire, Math.min(remaining, MAX_TIMER_DELAY_MS));
  };
  expire();
}

function handleAuthenticatedMessage(
  socket: WebSocket,
  state: ConnectionState,
  message: JsonRecord | undefined,
): void {
  if (!message) {
    send(socket, validationError([{ field: "message", message: "Debe ser JSON válido" }]).toBody());
    return;
  }

  if (message.type === "pong") {
    if (state.pongTimer) clearTimeout(state.pongTimer);
    delete state.pongTimer;
    return;
  }

  const channel = message.channel;
  if (
    (message.type !== "subscribe" && message.type !== "unsubscribe") ||
    typeof channel !== "string" ||
    !PRIVATE_CHANNELS.has(channel)
  ) {
    send(socket, validationError([
      { field: "message", message: "Tipo o canal privado no soportado" },
    ]).toBody());
    return;
  }

  if (message.type === "subscribe") {
    state.subscriptions.add(channel);
    send(socket, { type: "subscribed", channel });
  } else {
    state.subscriptions.delete(channel);
    send(socket, { type: "unsubscribed", channel });
  }
}

function acceptConnection(
  socket: WebSocket,
  authService: AuthService,
  timings: PrivateWebSocketTimings,
): void {
  const state: ConnectionState = {
    authenticated: false,
    closed: false,
    subscriptions: new Set(),
  };

  const rejectAuthentication = (): void => {
    closeWithError(socket, state, new ApiError("UNAUTHENTICATED"), 4001, "Unauthenticated");
  };
  state.authTimer = setTimeout(rejectAuthentication, timings.authTimeoutMs);

  state.pingTimer = setInterval(() => {
    if (state.closed || socket.readyState !== WebSocket.OPEN) return;
    send(socket, { type: "ping" });
    if (state.pongTimer) clearTimeout(state.pongTimer);
    state.pongTimer = setTimeout(() => {
      closeWithoutError(socket, state, 4000, "Heartbeat timeout");
    }, timings.pongTimeoutMs);
  }, timings.pingIntervalMs);

  socket.on("message", (data, isBinary) => {
    if (state.closed) return;
    const messageData = Array.isArray(data)
      ? Buffer.concat(data)
      : data instanceof ArrayBuffer
        ? Buffer.from(data)
        : Buffer.from(data.buffer, data.byteOffset, data.byteLength);
    const message = parseMessage(messageData, isBinary);
    if (!state.authenticated) {
      if (!message || message.type !== "auth" || typeof message.token !== "string") {
        rejectAuthentication();
        return;
      }
      const session = authService.authenticateSession(message.token);
      if (!session) {
        rejectAuthentication();
        return;
      }
      state.authenticated = true;
      if (state.authTimer) clearTimeout(state.authTimer);
      delete state.authTimer;
      scheduleExpiry(socket, state, session.expiresAt);
      send(socket, { type: "authenticated" });
      return;
    }
    handleAuthenticatedMessage(socket, state, message);
  });

  socket.on("close", () => {
    state.closed = true;
    state.subscriptions.clear();
    clearConnectionTimers(state);
  });
  socket.on("error", () => {
    // Errors are connection-local. No credential or payload is logged.
  });
}

export function attachPrivateWebSocket(
  server: HttpServer,
  authService: AuthService,
  timings: PrivateWebSocketTimings = DEFAULT_PRIVATE_WEBSOCKET_TIMINGS,
): () => void {
  const webSocketServer = new WebSocketServer({ noServer: true, maxPayload: 64 * 1024 });

  const onUpgrade = (request: IncomingMessage, socket: Duplex, head: Buffer): void => {
    let path: string;
    try {
      path = new URL(request.url ?? "", "http://localhost").pathname;
    } catch {
      return;
    }
    if (path !== "/api/v1/ws") return;

    try {
      webSocketServer.handleUpgrade(request, socket, head, (webSocket) => {
        webSocketServer.emit("connection", webSocket, request);
      });
    } catch {
      socket.destroy();
    }
  };

  server.on("upgrade", onUpgrade);
  webSocketServer.on("connection", (socket) => acceptConnection(socket, authService, timings));

  return () => {
    server.off("upgrade", onUpgrade);
    for (const client of webSocketServer.clients) client.terminate();
    webSocketServer.close();
  };
}

