 98	      } catch {
 99	        // Explicit logout remains local and safe when the server or network is unavailable.
100	      }
101	    }
102	    await handleUnauthenticated();
103	  }, [handleUnauthenticated]);
104	
105	  const value = useMemo<AuthContextValue>(() => ({
106	    phase,
107	    token,
108	    login,
109	    logout,
110	    handleUnauthenticated,
111	  }), [handleUnauthenticated, login, logout, phase, token]);
112	
113	  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
114	}
