  5	export type SocketStatus = "connecting" | "live" | "reconnecting" | "disconnected";
  6	
  7	export const RECONNECT_INITIAL_MS = 1_000;
  8	export const RECONNECT_MAX_MS = 30_000;
  9	export const RECONNECT_JITTER_MS = 500;
 10	
 11	export function reconnectDelay(attempt: number, random = Math.random): number {
 12	  const exponential = Math.min(RECONNECT_INITIAL_MS * (2 ** attempt), RECONNECT_MAX_MS);
 13	  const jitter = Math.round((random() * 2 - 1) * RECONNECT_JITTER_MS);
 14	  return Math.max(0, exponential + jitter);
 15	}
