  1	import type { Server as HttpServer, IncomingMessage } from "node:http";
  2	import type { Duplex } from "node:stream";
  3	import { WebSocket, WebSocketServer } from "ws";
  4	import { ApiError, validationError } from "./errors.js";
  5	import type { AuthService } from "./services/auth-service.js";
  6	
  7	export interface PrivateWebSocketTimings {
  8	  authTimeoutMs: number;
  9	  pingIntervalMs: number;
 10	  pongTimeoutMs: number;
 11	}
 12	
 13	export const DEFAULT_PRIVATE_WEBSOCKET_TIMINGS: Readonly<PrivateWebSocketTimings> = {
 14	  authTimeoutMs: 10_000,
 15	  pingIntervalMs: 30_000,
 16	  pongTimeoutMs: 10_000,
 17	};
 18	
 19	const PRIVATE_CHANNELS = new Set(["orders", "balances", "withdrawals"]);
 20	const MAX_TIMER_DELAY_MS = 2_147_483_647;
 21	
 22	interface JsonRecord {
 23	  [key: string]: unknown;
 24	}
 25	
 26	interface ConnectionState {
 27	  authenticated: boolean;
 28	  closed: boolean;
 29	  subscriptions: Set<string>;
 30	  authTimer?: ReturnType<typeof setTimeout>;
 31	  expiryTimer?: ReturnType<typeof setTimeout>;
 32	  pingTimer?: ReturnType<typeof setInterval>;
 33	  pongTimer?: ReturnType<typeof setTimeout>;
 34	}
 35	
 36	function isRecord(value: unknown): value is JsonRecord {
 37	  return value !== null && typeof value === "object" && !Array.isArray(value);
 38	}
 39	
 40	function encode(value: unknown): string {
 41	  return JSON.stringify(value);
 42	}
 43	
 44	function send(socket: WebSocket, value: unknown): void {
 45	  if (socket.readyState === WebSocket.OPEN) socket.send(encode(value));
 46	}
 47	
 48	function clearConnectionTimers(state: ConnectionState): void {
 49	  if (state.authTimer) clearTimeout(state.authTimer);
 50	  if (state.expiryTimer) clearTimeout(state.expiryTimer);
 51	  if (state.pingTimer) clearInterval(state.pingTimer);
 52	  if (state.pongTimer) clearTimeout(state.pongTimer);
 53	}
 54	
 55	function closeWithError(
 56	  socket: WebSocket,
 57	  state: ConnectionState,
 58	  error: ApiError,
 59	  closeCode: number,
 60	  reason: string,
 61	): void {
 62	  if (state.closed) return;
 63	  state.closed = true;
 64	  clearConnectionTimers(state);
 65	  if (socket.readyState !== WebSocket.OPEN) {
 66	    socket.terminate();
 67	    return;
 68	  }
 69	  socket.send(encode(error.toBody()), (sendError) => {
 70	    if (sendError) socket.terminate();
 71	    else socket.close(closeCode, reason);
 72	  });
 73	}
 74	
 75	function closeWithoutError(
 76	  socket: WebSocket,
 77	  state: ConnectionState,
 78	  closeCode: number,
 79	  reason: string,
 80	): void {
 81	  if (state.closed) return;
 82	  state.closed = true;
 83	  clearConnectionTimers(state);
 84	  if (socket.readyState === WebSocket.OPEN) socket.close(closeCode, reason);
 85	  else socket.terminate();
 86	}
 87	
 88	function parseMessage(data: Buffer, isBinary: boolean): JsonRecord | undefined {
 89	  if (isBinary) return undefined;
 90	  try {
 91	    const value: unknown = JSON.parse(data.toString("utf8"));
 92	    return isRecord(value) ? value : undefined;
 93	  } catch {
 94	    return undefined;
 95	  }
 96	}
 97	
 98	function scheduleExpiry(
 99	  socket: WebSocket,
100	  state: ConnectionState,
101	  expiresAt: string,
102	): void {
103	  const expire = (): void => {
104	    const remaining = Date.parse(expiresAt) - Date.now();
105	    if (remaining <= 0) {
106	      closeWithError(socket, state, new ApiError("UNAUTHENTICATED"), 4001, "Unauthenticated");
107	      return;
108	    }
109	    state.expiryTimer = setTimeout(expire, Math.min(remaining, MAX_TIMER_DELAY_MS));
110	  };
111	  expire();
112	}
113	
114	function handleAuthenticatedMessage(
115	  socket: WebSocket,
116	  state: ConnectionState,
117	  message: JsonRecord | undefined,
118	): void {
119	  if (!message) {
120	    send(socket, validationError([{ field: "message", message: "Debe ser JSON válido" }]).toBody());
121	    return;
122	  }
123	
124	  if (message.type === "pong") {
125	    if (state.pongTimer) clearTimeout(state.pongTimer);
126	    delete state.pongTimer;
127	    return;
128	  }
129	
130	  const channel = message.channel;
131	  if (
132	    (message.type !== "subscribe" && message.type !== "unsubscribe") ||
133	    typeof channel !== "string" ||
134	    !PRIVATE_CHANNELS.has(channel)
135	  ) {
136	    send(socket, validationError([
137	      { field: "message", message: "Tipo o canal privado no soportado" },
138	    ]).toBody());
139	    return;
140	  }
141	
142	  if (message.type === "subscribe") {
143	    state.subscriptions.add(channel);
144	    send(socket, { type: "subscribed", channel });
145	  } else {
146	    state.subscriptions.delete(channel);
147	    send(socket, { type: "unsubscribed", channel });
148	  }
149	}
150	
151	function acceptConnection(
152	  socket: WebSocket,
153	  authService: AuthService,
154	  timings: PrivateWebSocketTimings,
155	): void {
156	  const state: ConnectionState = {
157	    authenticated: false,
158	    closed: false,
159	    subscriptions: new Set(),
160	  };
161	
162	  const rejectAuthentication = (): void => {
163	    closeWithError(socket, state, new ApiError("UNAUTHENTICATED"), 4001, "Unauthenticated");
164	  };
165	  state.authTimer = setTimeout(rejectAuthentication, timings.authTimeoutMs);
166	
167	  state.pingTimer = setInterval(() => {
168	    if (state.closed || socket.readyState !== WebSocket.OPEN) return;
169	    send(socket, { type: "ping" });
170	    if (state.pongTimer) clearTimeout(state.pongTimer);
171	    state.pongTimer = setTimeout(() => {
172	      closeWithoutError(socket, state, 4000, "Heartbeat timeout");
173	    }, timings.pongTimeoutMs);
174	  }, timings.pingIntervalMs);
175	
176	  socket.on("message", (data, isBinary) => {
177	    if (state.closed) return;
178	    const messageData = Array.isArray(data)
179	      ? Buffer.concat(data)
180	      : data instanceof ArrayBuffer
181	        ? Buffer.from(data)
182	        : Buffer.from(data.buffer, data.byteOffset, data.byteLength);
183	    const message = parseMessage(messageData, isBinary);
184	    if (!state.authenticated) {
185	      if (!message || message.type !== "auth" || typeof message.token !== "string") {
186	        rejectAuthentication();
187	        return;
188	      }
189	      const session = authService.authenticateSession(message.token);
190	      if (!session) {
191	        rejectAuthentication();
192	        return;
193	      }
194	      state.authenticated = true;
195	      if (state.authTimer) clearTimeout(state.authTimer);
196	      delete state.authTimer;
197	      scheduleExpiry(socket, state, session.expiresAt);
198	      send(socket, { type: "authenticated" });
199	      return;
200	    }
201	    handleAuthenticatedMessage(socket, state, message);
202	  });
203	
204	  socket.on("close", () => {
205	    state.closed = true;
206	    state.subscriptions.clear();
207	    clearConnectionTimers(state);
208	  });
209	  socket.on("error", () => {
210	    // Errors are connection-local. No credential or payload is logged.
211	  });
212	}
213	
214	export function attachPrivateWebSocket(
215	  server: HttpServer,
216	  authService: AuthService,
217	  timings: PrivateWebSocketTimings = DEFAULT_PRIVATE_WEBSOCKET_TIMINGS,
218	): () => void {
219	  const webSocketServer = new WebSocketServer({ noServer: true, maxPayload: 64 * 1024 });
220	
221	  const onUpgrade = (request: IncomingMessage, socket: Duplex, head: Buffer): void => {
222	    let path: string;
223	    try {
224	      path = new URL(request.url ?? "", "http://localhost").pathname;
225	    } catch {
226	      return;
227	    }
228	    if (path !== "/api/v1/ws") return;
229	
230	    try {
231	      webSocketServer.handleUpgrade(request, socket, head, (webSocket) => {
232	        webSocketServer.emit("connection", webSocket, request);
233	      });
234	    } catch {
235	      socket.destroy();
236	    }
237	  };
238	
239	  server.on("upgrade", onUpgrade);
240	  webSocketServer.on("connection", (socket) => acceptConnection(socket, authService, timings));
241	
242	  return () => {
243	    server.off("upgrade", onUpgrade);
244	    for (const client of webSocketServer.clients) client.terminate();
245	    webSocketServer.close();
246	  };
247	}

  1	import { randomUUID } from "node:crypto";
  2	import type { Store, AddressRow } from "../database.js";
  3	import { addressRecord } from "../database.js";
  4	import { ApiError } from "../errors.js";
  5	import { CHAIN_ID, deriveNextValidAddress, type HmacSha512 } from "../crypto/wallet.js";
  6	
  7	export interface DepositAddressAssignedEvent {
  8	  eventId: string;
  9	  accountId: string;
 10	  payload: {
 11	    accountId: string;
 12	    addressIndex: number;
 13	    address: string;
 14	    chainId: "11155111";
 15	  };
 16	  occurredAt: string;
 17	}
 18	
 19	export class WalletService {
 20	  constructor(
 21	    private readonly store: Store,
 22	    private readonly hmac?: HmacSha512,
 23	  ) {}
 24	
 25	  getOrAssign(accountId: string): AddressRow {
 26	    const existing = this.store.findAddress(accountId);
 27	    if (existing) return existing;
 28	    if (!this.store.findAccountById(accountId)) {
 29	      throw new ApiError("ACCOUNT_NOT_FOUND", { accountId });
 30	    }
 31	    return this.store.transaction(() => this.assignInsideTransaction(accountId));
 32	  }
 33	
 34	  assignInsideTransaction(accountId: string): AddressRow {
 35	    const existing = this.store.findAddress(accountId);
 36	    if (existing) return existing;
 37	    const maxRow = this.store.db.prepare(
 38	      "SELECT MAX(address_index) AS max_index FROM deposit_addresses",
 39	    ).get() as { max_index: number | null };
 40	    const nextIndex = maxRow.max_index === null ? 0 : maxRow.max_index + 1;
 41	    const derived = this.hmac
 42	      ? deriveNextValidAddress(this.store.seed, nextIndex, this.hmac)
 43	      : deriveNextValidAddress(this.store.seed, nextIndex);
 44	    const createdAt = new Date().toISOString();
 45	    for (const skippedIndex of derived.skippedIndices ?? []) {
 46	      this.store.db.prepare(
 47	        `INSERT INTO skipped_address_indices (address_index, reason, occurred_at)
 48	         VALUES (?, 'INVALID_BIP32_CHILD', ?)`,
 49	      ).run(skippedIndex, createdAt);
 50	    }
 51	    const row = addressRecord(
 52	      accountId,
 53	      derived.addressIndex,
 54	      derived.address,
 55	      derived.derivationPath,
 56	      createdAt,
 57	    );
 58	    this.store.db.prepare(
 59	      `INSERT INTO deposit_addresses
 60	       (account_id, address_index, address, derivation_path, network, chain_id, created_at)
 61	       VALUES (?, ?, ?, ?, ?, ?, ?)`,
 62	    ).run(
 63	      row.account_id,
 64	      row.address_index,
 65	      row.address,
 66	      row.derivation_path,
 67	      row.network,
 68	      row.chain_id,
 69	      row.created_at,
 70	    );
 71	    this.store.db.prepare(
 72	      `INSERT INTO domain_events
 73	       (event_id, event_type, account_id, payload, occurred_at)
 74	       VALUES (?, 'DepositAddressAssigned', ?, ?, ?)`,
 75	    ).run(
 76	      randomUUID(),
 77	      accountId,
 78	      JSON.stringify({
 79	        accountId,
 80	        addressIndex: row.address_index,
 81	        address: row.address,
 82	        chainId: CHAIN_ID,
 83	      }),
 84	      createdAt,
 85	    );
 86	    return row;
 87	  }
 88	
 89	  listAssigned(): AddressRow[] {
 90	    return this.store.getAssignedAddresses();
 91	  }
 92	
 93	  listAssignedEvents(): DepositAddressAssignedEvent[] {
 94	    const rows = this.store.db.prepare(
 95	      `SELECT event_id, account_id, payload, occurred_at
 96	       FROM domain_events WHERE event_type = 'DepositAddressAssigned' ORDER BY occurred_at, event_id`,
 97	    ).all() as unknown as Array<{
 98	      event_id: string;
 99	      account_id: string;
100	      payload: string;
101	      occurred_at: string;
102	    }>;
103	    return rows.map((row) => ({
104	      eventId: row.event_id,
105	      accountId: row.account_id,
106	      payload: JSON.parse(row.payload) as DepositAddressAssignedEvent["payload"],
107	      occurredAt: row.occurred_at,
108	    }));
109	  }
110	}

