  1	import {
  2	  createContext,
  3	  type PropsWithChildren,
  4	  useCallback,
  5	  useContext,
  6	  useEffect,
  7	  useMemo,
  8	  useRef,
  9	  useState,
 10	} from "react";
 11	import { AppState } from "react-native";
 12	import { loginRequest, logoutRequest } from "../api/client";
 13	import { sessionStorage } from "./session-storage";
 14	
 15	type SessionPhase = "restoring" | "guest" | "authenticated";
 16	
 17	interface AuthContextValue {
 18	  phase: SessionPhase;
 19	  token: string | null;
 20	  login(email: string, password: string): Promise<void>;
 21	  logout(): Promise<void>;
 22	  handleUnauthenticated(): Promise<void>;
 23	}
 24	
 25	const AuthContext = createContext<AuthContextValue | undefined>(undefined);
 26	
 27	export function AuthProvider({ children }: PropsWithChildren) {
 28	  const [phase, setPhase] = useState<SessionPhase>("restoring");
 29	  const [token, setToken] = useState<string | null>(null);
 30	  const tokenRef = useRef<string | null>(null);
 31	  const storageReadFailedRef = useRef(false);
 32	  const logoutPromiseRef = useRef<Promise<void> | null>(null);
 33	
 34	  const restore = useCallback(async () => {
 35	    try {
 36	      const restored = await sessionStorage.read();
 37	      storageReadFailedRef.current = false;
 38	      tokenRef.current = restored;
 39	      setToken(restored);
 40	      setPhase(restored ? "authenticated" : "guest");
 41	    } catch {
 42	      storageReadFailedRef.current = true;
 43	      tokenRef.current = null;
 44	      setToken(null);
 45	      setPhase("guest");
 46	    }
 47	  }, []);
 48	
 49	  useEffect(() => {
 50	    void restore();
 51	  }, [restore]);
 52	
 53	  useEffect(() => {
 54	    const subscription = AppState.addEventListener("change", (nextState) => {
 55	      if (nextState === "active" && storageReadFailedRef.current && tokenRef.current === null) {
 56	        void restore();
 57	      }
 58	    });
 59	    return () => subscription.remove();
 60	  }, [restore]);
 61	
 62	  const handleUnauthenticated = useCallback(async (): Promise<void> => {
 63	    if (logoutPromiseRef.current) return logoutPromiseRef.current;
 64	    if (tokenRef.current === null) return;
 65	
 66	    const operation = (async () => {
 67	      try {
 68	        await sessionStorage.remove();
 69	      } catch {
 70	        // Memory is still cleared. A later launch treats an inaccessible store as no session.
 71	      } finally {
 72	        tokenRef.current = null;
 73	        setToken(null);
 74	        setPhase("guest");
 75	      }
 76	    })();
 77	    logoutPromiseRef.current = operation;
 78	    try {
 79	      await operation;
 80	    } finally {
 81	      if (logoutPromiseRef.current === operation) logoutPromiseRef.current = null;
 82	    }
 83	  }, []);
 84	
 85	  const login = useCallback(async (email: string, password: string): Promise<void> => {
 86	    const response = await loginRequest(email, password);
 87	    await sessionStorage.write(response.token);
 88	    tokenRef.current = response.token;
 89	    setToken(response.token);
 90	    setPhase("authenticated");
 91	  }, []);
 92	
 93	  const logout = useCallback(async (): Promise<void> => {
 94	    const currentToken = tokenRef.current;
 95	    if (currentToken) {
 96	      try {
 97	        await logoutRequest(currentToken, handleUnauthenticated);
 98	      } catch {
 99	        // Explicit logout remains local and safe when the server or network is unavailable.
100	      }
101	    }
102	    await handleUnauthenticated();
103	  }, [handleUnauthenticated]);
104	
105	  const value = useMemo<AuthContextValue>(() => ({
106	    phase,
107	    token,
108	    login,
109	    logout,
110	    handleUnauthenticated,
111	  }), [handleUnauthenticated, login, logout, phase, token]);
112	
113	  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
114	}
115	
116	export function useAuth(): AuthContextValue {
117	  const value = useContext(AuthContext);
118	  if (!value) throw new Error("useAuth debe usarse dentro de AuthProvider");
119	  return value;
120	}

 1	import * as SecureStore from "expo-secure-store";
 2	
 3	const SESSION_TOKEN_KEY = "exchange.session-token";
 4	
 5	export const sessionStorage = {
 6	  read(): Promise<string | null> {
 7	    return SecureStore.getItemAsync(SESSION_TOKEN_KEY);
 8	  },
 9	
10	  write(token: string): Promise<void> {
11	    return SecureStore.setItemAsync(SESSION_TOKEN_KEY, token, {
12	      keychainAccessible: SecureStore.AFTER_FIRST_UNLOCK_THIS_DEVICE_ONLY,
13	    });
14	  },
15	
16	  remove(): Promise<void> {
17	    return SecureStore.deleteItemAsync(SESSION_TOKEN_KEY);
18	  },
19	};
20	
21	export { SESSION_TOKEN_KEY };

