  4	export class ApiClientError extends Error {
  5	  constructor(
  6	    public readonly code: string,
  7	    message: string,
  8	    public readonly status: number,
  9	    public readonly details?: Record<string, unknown>,
 10	  ) {
 11	    super(message);
 12	    this.name = "ApiClientError";
 13	  }
 14	}
 15	
 16	function isRecord(value: unknown): value is Record<string, unknown> {
 17	  return value !== null && typeof value === "object" && !Array.isArray(value);
 18	}
 19	
 20	function parseError(value: unknown, status: number): ApiClientError {
 21	  if (isRecord(value) && isRecord(value.error)) {
 22	    const code = typeof value.error.code === "string" ? value.error.code : "INTERNAL_ERROR";
 23	    const message = typeof value.error.message === "string"
 24	      ? value.error.message
 25	      : "No se pudo completar la solicitud.";
 26	    const details = isRecord(value.error.details) ? value.error.details : undefined;
 27	    return new ApiClientError(code, message, status, details);
 28	  }
 29	  return new ApiClientError("INTERNAL_ERROR", "No se pudo completar la solicitud.", status);
 30	}
 31	
 32	async function readJson(response: Response): Promise<unknown> {
 33	  try {
 34	    return await response.json() as unknown;
 35	  } catch {
 36	    return undefined;
 37	  }
 38	}
 39	
 40	async function requestJson(
 41	  path: string,
 42	  init: RequestInit,
 43	  token?: string,
 44	  onUnauthenticated?: () => Promise<void>,
 45	): Promise<unknown> {
 46	  const headers = new Headers(init.headers);
 47	  headers.set("Accept", "application/json");
 48	  if (init.body !== undefined) headers.set("Content-Type", "application/json");
 49	  if (token) headers.set("Authorization", `Bearer ${token}`);
 50	
 51	  const response = await fetch(`${getApiBaseUrl()}${path}`, { ...init, headers });
 52	  const body = response.status === 204 ? undefined : await readJson(response);
 53	  if (!response.ok) {
 54	    const error = parseError(body as ApiErrorBody, response.status);
 55	    if (response.status === 401 && error.code === "UNAUTHENTICATED" && onUnauthenticated) {
 56	      await onUnauthenticated();
 57	    }
 58	    throw error;
 59	  }
 60	  return body;
 61	}
 62	
 63	export async function loginRequest(email: string, password: string): Promise<LoginResponse> {
 64	  const body = await requestJson("/auth/login", {
 65	    method: "POST",
 66	    body: JSON.stringify({ email, password }),
 67	  });
 68	  if (!isRecord(body) || typeof body.token !== "string" || body.token.length === 0 ||
 69	      typeof body.expiresAt !== "string") {
 70	    throw new ApiClientError("INTERNAL_ERROR", "La respuesta de inicio de sesión no es válida.", 500);
 71	  }
 72	  return { token: body.token, expiresAt: body.expiresAt };
 73	}
