  1	import { useEffect, useState } from "react";
  2	import { AppState } from "react-native";
  3	import { getWebSocketUrl } from "../config";
  4	
  5	export type SocketStatus = "connecting" | "live" | "reconnecting" | "disconnected";
  6	
  7	export const RECONNECT_INITIAL_MS = 1_000;
  8	export const RECONNECT_MAX_MS = 30_000;
  9	export const RECONNECT_JITTER_MS = 500;
 10	
 11	export function reconnectDelay(attempt: number, random = Math.random): number {
 12	  const exponential = Math.min(RECONNECT_INITIAL_MS * (2 ** attempt), RECONNECT_MAX_MS);
 13	  const jitter = Math.round((random() * 2 - 1) * RECONNECT_JITTER_MS);
 14	  return Math.max(0, exponential + jitter);
 15	}
 16	
 17	interface PrivateSocketOptions {
 18	  token: string;
 19	  onUnauthenticated: () => Promise<void>;
 20	}
 21	
 22	export function usePrivateSocket({ token, onUnauthenticated }: PrivateSocketOptions): SocketStatus {
 23	  const [status, setStatus] = useState<SocketStatus>("connecting");
 24	
 25	  useEffect(() => {
 26	    let socket: WebSocket | null = null;
 27	    let retryTimer: ReturnType<typeof setTimeout> | null = null;
 28	    let attempt = 0;
 29	    let disposed = false;
 30	    let foreground = AppState.currentState === "active";
 31	    let authenticationFailed = false;
 32	
 33	    const clearRetry = () => {
 34	      if (retryTimer) clearTimeout(retryTimer);
 35	      retryTimer = null;
 36	    };
 37	
 38	    const forceLogout = () => {
 39	      if (authenticationFailed) return;
 40	      authenticationFailed = true;
 41	      clearRetry();
 42	      void onUnauthenticated();
 43	    };
 44	
 45	    const scheduleReconnect = () => {
 46	      if (disposed || !foreground || authenticationFailed || retryTimer) return;
 47	      setStatus("reconnecting");
 48	      const delay = reconnectDelay(attempt);
 49	      attempt += 1;
 50	      retryTimer = setTimeout(() => {
 51	        retryTimer = null;
 52	        connect();
 53	      }, delay);
 54	    };
 55	
 56	    const connect = () => {
 57	      if (disposed || !foreground || authenticationFailed) return;
 58	      clearRetry();
 59	      setStatus(attempt === 0 ? "connecting" : "reconnecting");
 60	      const current = new WebSocket(getWebSocketUrl());
 61	      socket = current;
 62	
 63	      current.onopen = () => {
 64	        if (disposed || !foreground || current !== socket) return;
 65	        current.send(JSON.stringify({ type: "auth", token }));
 66	      };
 67	
 68	      current.onmessage = (event) => {
 69	        if (current !== socket || typeof event.data !== "string") return;
 70	        let message: unknown;
 71	        try {
 72	          message = JSON.parse(event.data) as unknown;
 73	        } catch {
 74	          return;
 75	        }
 76	        if (!message || typeof message !== "object") return;
 77	        const record = message as Record<string, unknown>;
 78	        if (record.type === "authenticated") {
 79	          attempt = 0;
 80	          setStatus("live");
 81	          return;
 82	        }
 83	        if (record.type === "ping" && current.readyState === WebSocket.OPEN) {
 84	          current.send(JSON.stringify({ type: "pong" }));
 85	          return;
 86	        }
 87	        const error = record.error;
 88	        if (error && typeof error === "object" &&
 89	            (error as Record<string, unknown>).code === "UNAUTHENTICATED") {
 90	          forceLogout();
 91	          current.close();
 92	        }
 93	      };
 94	
 95	      current.onerror = () => {
 96	        // onclose owns reconnection; no diagnostic includes the token or password.
 97	      };
 98	
 99	      current.onclose = (event) => {
100	        if (current === socket) socket = null;
101	        if (event.code === 4001) forceLogout();
102	        scheduleReconnect();
103	      };
104	    };
105	
106	    const appStateSubscription = AppState.addEventListener("change", (nextState) => {
107	      if (nextState === "active") {
108	        foreground = true;
109	        if (!authenticationFailed) connect();
110	        return;
111	      }
112	      foreground = false;
113	      clearRetry();
114	      setStatus("disconnected");
115	      const current = socket;
116	      socket = null;
117	      current?.close();
118	    });
119	
120	    if (foreground) connect();
121	
122	    return () => {
123	      disposed = true;
124	      foreground = false;
125	      clearRetry();
126	      appStateSubscription.remove();
127	      const current = socket;
128	      socket = null;
129	      current?.close();
130	    };
131	  }, [onUnauthenticated, token]);
132	
133	  return status;
134	}

