import { FormEvent, useEffect, useRef, useState } from "react";
import { ApiResponseError, login, NetworkError } from "./api";
import { consumeExpirationNotice, persistSession } from "./session";

type FieldName = "email" | "password";
type FieldErrors = Partial<Record<FieldName, string>>;

interface LoginPageProps {
  onAuthenticated: () => void;
}

function validationMessages(details: unknown): { fields: FieldErrors; general?: string } {
  if (details === null || typeof details !== "object" || Array.isArray(details)) {
    return { fields: {}, general: "Revisá los datos ingresados" };
  }
  const issues = (details as Record<string, unknown>).issues;
  if (!Array.isArray(issues)) return { fields: {}, general: "Revisá los datos ingresados" };

  const fields: FieldErrors = {};
  for (const issue of issues) {
    if (issue === null || typeof issue !== "object" || Array.isArray(issue)) continue;
    const item = issue as Record<string, unknown>;
    const field = item.field;
    const message = item.message;
    if ((field === "email" || field === "password") && typeof message === "string") {
      fields[field] = message.slice(0, 200);
    }
  }
  return Object.keys(fields).length > 0
    ? { fields }
    : { fields, general: "Revisá los datos ingresados" };
}

export function LoginPage({ onAuthenticated }: LoginPageProps) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [message, setMessage] = useState<string | null>(
    consumeExpirationNotice() ? "Tu sesión expiró, ingresá nuevamente" : null,
  );
  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});
  const [retrySeconds, setRetrySeconds] = useState(0);
  const [retryAvailable, setRetryAvailable] = useState(false);
  const inFlight = useRef(false);
  const retryDeadline = useRef<number | null>(null);

  useEffect(() => {
    if (retrySeconds <= 0) return;
    const timer = window.setTimeout(() => {
      const deadline = retryDeadline.current;
      if (deadline === null) {
        setRetrySeconds(0);
        return;
      }
      const remaining = Math.max(0, Math.ceil((deadline - Date.now()) / 1000));
      if (remaining === 0) retryDeadline.current = null;
      setRetrySeconds(remaining);
    }, 1000);
    return () => window.clearTimeout(timer);
  }, [retrySeconds]);

  const submit = async () => {
    if (inFlight.current || email.length === 0 || password.length === 0 || retrySeconds > 0) return;
    inFlight.current = true;
    setSubmitting(true);
    setMessage(null);
    setFieldErrors({});
    setRetryAvailable(false);
    try {
      const session = await login(email, password);
      persistSession(session);
      onAuthenticated();
    } catch (error) {
      if (error instanceof ApiResponseError) {
        switch (error.code) {
          case "INVALID_CREDENTIALS":
            setMessage("Email o contraseña incorrectos");
            setPassword("");
            break;
          case "VALIDATION_ERROR": {
            const validation = validationMessages(error.details);
            setFieldErrors(validation.fields);
            setMessage(validation.general ?? null);
            break;
          }
          case "RATE_LIMITED": {
            const details = error.details;
            const retryAfter = details !== null && typeof details === "object" && !Array.isArray(details)
              ? (details as Record<string, unknown>).retryAfterSeconds
              : undefined;
            const seconds = typeof retryAfter === "number" && Number.isInteger(retryAfter) && retryAfter > 0
              ? retryAfter
              : 1;
            retryDeadline.current = Date.now() + seconds * 1000;
            setRetrySeconds(seconds);
            break;
          }
          case "INTERNAL_ERROR":
            setMessage("No se pudo conectar, reintentá");
            setRetryAvailable(true);
            break;
          default:
            setMessage("No se pudo conectar, reintentá");
            setRetryAvailable(true);
        }
      } else if (error instanceof NetworkError) {
        setMessage("No se pudo conectar, reintentá");
        setRetryAvailable(true);
      } else {
        setMessage("No se pudo conectar, reintentá");
        setRetryAvailable(true);
      }
    } finally {
      inFlight.current = false;
      setSubmitting(false);
    }
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    void submit();
  };

  const disabled = email.length === 0 || password.length === 0 || submitting || retrySeconds > 0;

  return (
    <main className="login-layout">
      <section className="brand-panel" aria-label="Axis Exchange">
        <div className="brand-mark" aria-hidden="true"><span>A</span></div>
        <p className="eyebrow">ETH / USDC</p>
        <h1>Tu mercado.<br />En un solo eje.</h1>
        <p className="brand-copy">
          Accedé a tu cuenta para operar en el mercado de Sepolia con una sesión segura.
        </p>
        <div className="market-pulse" aria-hidden="true">
          <span className="pulse-dot" />
          <span>Mercado disponible</span>
        </div>
      </section>

      <section className="form-panel">
        <div className="form-shell">
          <div className="mobile-brand">
            <div className="brand-mark brand-mark-small" aria-hidden="true"><span>A</span></div>
            <span>AXIS</span>
          </div>
          <header>
            <p className="eyebrow">Bienvenido de nuevo</p>
            <h2>Ingresá a tu cuenta</h2>
            <p>Usá las credenciales con las que te registraste.</p>
          </header>

          {message && (
            <div className="notice" role="alert">
              <span aria-hidden="true">!</span>
              <p>{message}</p>
            </div>
          )}

          {retrySeconds > 0 && (
            <div className="notice notice-wait" role="status" aria-live="polite">
              <span aria-hidden="true">◷</span>
              <p>Esperá {retrySeconds} {retrySeconds === 1 ? "segundo" : "segundos"} antes de volver a intentar.</p>
            </div>
          )}

          <form onSubmit={handleSubmit} noValidate aria-busy={submitting}>
            <div className="field-group">
              <label htmlFor="email">Email</label>
              <input
                id="email"
                name="email"
                type="email"
                inputMode="email"
                autoComplete="username"
                value={email}
                onChange={(event) => {
                  setEmail(event.target.value);
                  setFieldErrors((current) => ({ ...current, email: undefined }));
                }}
                aria-invalid={fieldErrors.email ? "true" : "false"}
                aria-describedby={fieldErrors.email ? "email-error" : undefined}
                placeholder="vos@ejemplo.com"
                required
              />
              {fieldErrors.email && <p className="field-error" id="email-error">{fieldErrors.email}</p>}
            </div>

            <div className="field-group">
              <label htmlFor="password">Contraseña</label>
              <input
                id="password"
                name="password"
                type="password"
                autoComplete="current-password"
                value={password}
                onChange={(event) => {
                  setPassword(event.target.value);
                  setFieldErrors((current) => ({ ...current, password: undefined }));
                }}
                aria-invalid={fieldErrors.password ? "true" : "false"}
                aria-describedby={fieldErrors.password ? "password-error" : undefined}
                placeholder="Tu contraseña"
                required
              />
              {fieldErrors.password && <p className="field-error" id="password-error">{fieldErrors.password}</p>}
            </div>

            <button className="primary-button" type="submit" disabled={disabled}>
              {submitting ? <><span className="spinner" aria-hidden="true" />Ingresando…</> : "Ingresar"}
            </button>

            {retryAvailable && (
              <button className="retry-button" type="button" disabled={disabled} onClick={() => void submit()}>
                Reintentar
              </button>
            )}
          </form>

          <p className="security-note"><span aria-hidden="true">◇</span> Tu sesión se valida de forma segura con el servidor.</p>
export type ErrorDetails = Record<string, unknown>;

const HTTP_STATUS: Readonly<Record<string, number>> = {
  UNAUTHENTICATED: 401,
  INVALID_CREDENTIALS: 401,
  UNAUTHORIZED: 403,
  VALIDATION_ERROR: 422,
  CHAIN_ID_MISMATCH: 422,
  NOT_FOUND: 404,
  ACCOUNT_NOT_FOUND: 404,
  METHOD_NOT_ALLOWED: 405,
  EMAIL_ALREADY_EXISTS: 409,
  RATE_LIMITED: 429,
  INTERNAL_ERROR: 500,
};

const MESSAGES: Readonly<Record<string, string>> = {
  UNAUTHENTICATED: "Se requiere una credencial válida.",
  INVALID_CREDENTIALS: "Las credenciales son incorrectas.",
  UNAUTHORIZED: "La credencial no autoriza esta operación.",
  VALIDATION_ERROR: "La solicitud no cumple el esquema esperado.",
  CHAIN_ID_MISMATCH: "La red solicitada no es Sepolia.",
  NOT_FOUND: "El recurso solicitado no existe.",
  ACCOUNT_NOT_FOUND: "La cuenta solicitada no existe.",
  METHOD_NOT_ALLOWED: "El método HTTP no está permitido para esta ruta.",
  EMAIL_ALREADY_EXISTS: "Ya existe una cuenta para el email indicado.",
  RATE_LIMITED: "Se superó el límite de solicitudes permitido.",
  INTERNAL_ERROR: "Ocurrió un error interno.",
};

export class ApiError extends Error {
  readonly code: string;
  readonly status: number;
  readonly details?: ErrorDetails;

  constructor(code: string, details?: ErrorDetails, message?: string, status?: number) {
    super(message ?? MESSAGES[code] ?? MESSAGES.INTERNAL_ERROR);
    this.name = "ApiError";
    this.code = code;
    this.status = status ?? HTTP_STATUS[code] ?? 500;
    if (details !== undefined) this.details = details;
  }

  toBody(): { error: { code: string; message: string; details?: ErrorDetails } } {
    const error: { code: string; message: string; details?: ErrorDetails } = {
      code: this.code,
      message: this.message,
    };
    if (this.details !== undefined) error.details = this.details;
    return { error };
  }
}

export interface ValidationIssue {
  field: string;
  message: string;
}

export function validationError(issues: ValidationIssue[]): ApiError {
  return new ApiError("VALIDATION_ERROR", { issues });
}

