 import * as SecureStore from "expo-secure-store";

 const SESSION_TOKEN_KEY = "exchange.session-token";
+const SIGNED_OUT_VALUE = "exchange.signed-out";
+const DELETE_RETRY_MAX_MS = 1_000;
+
+let pendingRemoval: Promise<void> | null = null;
+
+function delay(milliseconds: number): Promise<void> {
+  return new Promise((resolve) => setTimeout(resolve, milliseconds));
+}
+
+async function removePersistedSession(): Promise<void> {
+  // Overwrite the token before deleting it. If SecureStore temporarily refuses the
+  // deletion, a cold start sees this non-secret tombstone instead of restoring the
+  // former session. The deletion itself is still retried until it succeeds.
+  let retryDelay = 50;
+  for (;;) {
+    try {
+      await SecureStore.setItemAsync(SESSION_TOKEN_KEY, SIGNED_OUT_VALUE, {
+        keychainAccessible: SecureStore.AFTER_FIRST_UNLOCK_THIS_DEVICE_ONLY,
+      });
+      break;
+    } catch {
+      await delay(retryDelay);
+      retryDelay = Math.min(retryDelay * 2, DELETE_RETRY_MAX_MS);
+    }
+  }
+
+  retryDelay = 50;
+  for (;;) {
+    try {
+      await SecureStore.deleteItemAsync(SESSION_TOKEN_KEY);
+      return;
+    } catch {
+      await delay(retryDelay);
+      retryDelay = Math.min(retryDelay * 2, DELETE_RETRY_MAX_MS);
+    }
+  }
+}

